const w = $input.first().json.body || $input.first().json;
const s = w.execution_summary || {};
const r = s.results || {};
const q = s.question || {};
const rawTranscript = w.transcript || [];
const callDurationSecs = w.call_duration_secs || null;
const audio = w.audio || null;

let transcript = '';
if (Array.isArray(rawTranscript) && rawTranscript.length > 0) {
  transcript = rawTranscript.map(t => {
    const role = t.role || 'unknown';
    const msg = t.text || t.message || t.content || '';
    return role + ': ' + msg;
  }).join(String.fromCharCode(10));
}

// Derive per-test failures + category summary from visibleTests.details
// (the backend sends details[], not by_category/failures).
const details = Array.isArray(r.visibleTests?.details) ? r.visibleTests.details : [];
const derivedFailures = details.filter(d => d && d.passed === false).map(d => ({
  name: d.name, tags: d.tags || [], expected: d.expected, actual: d.actual, error: d.error || null
}));
const catCounts = {};
for (const d of details) {
  for (const tag of (Array.isArray(d.tags) && d.tags.length ? d.tags : ['uncategorized'])) {
    catCounts[tag] = catCounts[tag] || { pass: 0, fail: 0 };
    catCounts[tag][d.passed ? 'pass' : 'fail']++;
  }
}
const derivedByCategory = {};
for (const [tag, c] of Object.entries(catCounts)) {
  derivedByCategory[tag] = c.fail === 0 ? 'pass' : c.fail + ' fail';
}
const lines = [
  'QUESTION: ' + (s.questionTitle || '?') + ' (' + (s.difficulty || '?') + ')',
  'CONSTRAINTS: ' + (q.constraints || 'Not specified'),
  'CODE (' + (s.language || '?') + '):',
  s.code || 'none',
  'TEST RESULTS:',
  'TOTAL TESTS PASSED: ' + ((r.visibleTests?.passed||0) + (r.hiddenTests?.passed||0)) + '/' + ((r.visibleTests?.total||0) + (r.hiddenTests?.total||0)),
  'Visible: ' + (r.visibleTests?.passed||0) + '/' + (r.visibleTests?.total||0),
  'Hidden: ' + (r.hiddenTests?.passed||0) + '/' + (r.hiddenTests?.total||0),
  'By category: ' + JSON.stringify(r.by_category || r.byCategory || derivedByCategory),
  'Failures: ' + JSON.stringify(r.failures || derivedFailures),
  'COMPLETED: ' + (s.completed === true ? 'Yes' : 'No'),
  'PHASE: ' + (s.reachedPhase || s.reached_phase || '?'),
  'TIME: ' + (s.timeTakenMinutes || '?') + ' / ' + (s.timeBudgetMinutes || '?') + ' min',
  'HINTS: ' + JSON.stringify(s.hintLog || []),
  'ANSWER KEY - Solutions: ' + (q.solutions ? JSON.stringify(q.solutions, null, 1) : 'N/A'),
  'ANSWER KEY - Mistakes: ' + ((q.commonMistakes || q.common_mistakes) ? JSON.stringify(q.commonMistakes || q.common_mistakes) : 'N/A'),
  'ANSWER KEY - Follow-ups: ' + ((q.followUps || q.follow_ups) ? JSON.stringify(q.followUps || q.follow_ups) : 'N/A'),
  'TRANSCRIPT:',
  transcript || 'Not available'
];
return [{json: {userMessage: lines.join(String.fromCharCode(10)), transcript: rawTranscript, audio: audio, callDurationSecs: callDurationSecs}}];

const item = $input.first().json;
const fp = $('Format prompt').first().json;
let c = '';
if (item.output?.[0]?.content?.[0]?.text) {
  c = item.output[0].content[0].text;
} else if (item.output?.[0]?.text) {
  c = item.output[0].text;
} else if (typeof item.output === 'string') {
  c = item.output;
} else if (item.message?.content) {
  c = item.message.content;
}
const m = c.match(/```(?:json)?\s*([\s\S]*?)```/);
if (m) c = m[1].trim();
let fb;
try { fb = JSON.parse(c); } catch(e) { fb = { raw: c.substring(0,2000), error: e.message }; }
return [{json: { ...fb, transcript: fp.transcript || [], audio: fp.audio || null, callDurationSecs: fp.callDurationSecs || null }}];

